using System;using System.IO;using System.Drawing;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
namespace Folha {
// Isolated, invisible integration test. Never opens the user's profile or changes their documents.
static class PdfQa {
 public static void Run(string list,string output){Application.EnableVisualStyles();var files=File.ReadAllLines(list);var root=Path.Combine(Path.GetDirectoryName(output),"webview-qa-"+J.Id());var form=new QaForm();var view=new WebView2{Dock=DockStyle.Fill};form.Controls.Add(view);var timer=new System.Windows.Forms.Timer{Interval=180000};timer.Tick+=(s,e)=>{File.WriteAllText(output,"TIMEOUT");Environment.ExitCode=1;form.Close();};form.Load+=async(s,e)=>{try{var env=await CoreWebView2Environment.CreateAsync(null,root);await view.EnsureCoreWebView2Async(env);var c=view.CoreWebView2;c.SetVirtualHostNameToFolderMapping("folha.local",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"web"),CoreWebView2HostResourceAccessKind.DenyCors);c.AddWebResourceRequestedFilter("https://folha-data.local/data/*",CoreWebView2WebResourceContext.All,CoreWebView2WebResourceRequestSourceKinds.All);c.WebResourceRequested+=(a,b)=>{try{var i=int.Parse(new Uri(b.Request.Uri).Segments[2].Trim('/'));var stream=new FileStream(files[i],FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);b.Response=env.CreateWebResourceResponse(stream,200,"OK","Content-Type: application/pdf\r\nContent-Length: "+stream.Length+"\r\nAccess-Control-Allow-Origin: https://folha.local\r\nCache-Control: no-store");}catch{b.Response=env.CreateWebResourceResponse(null,404,"Not Found","");}};c.WebMessageReceived+=(a,b)=>{File.WriteAllText(output,b.WebMessageAsJson);Environment.ExitCode=b.WebMessageAsJson.Contains("FAIL")?1:0;timer.Stop();form.Close();};c.Navigate("https://folha.local/pdf-qa.html?count="+files.Length);timer.Start();}catch(Exception err){File.WriteAllText(output,err.ToString());Environment.ExitCode=1;form.Close();}};Application.Run(form);}
 sealed class QaForm:Form {public QaForm(){ShowInTaskbar=false;Opacity=0;StartPosition=FormStartPosition.Manual;Location=new Point(-32000,-32000);Size=new Size(900,700);}protected override bool ShowWithoutActivation{get{return true;}}}
}
}

